// 1. Authentication
if (!msg.req.headers['x-session-id']) {
    msg.payload = { error: "Unauthorized: Missing XsessionID header" };
    msg.statusCode = 401;
    return [null, msg]; // Send to second output (error)
}

// 2. Extract Group ID
var group_id = msg.req.query.group_id || "default";

// 3. Prepare Payload for Flask
if (msg.req.files && msg.req.files.length > 0) {
    var file = msg.req.files[0];
    msg.payload = {
        "image": {
            "value": file.buffer,
            "options": {
                "filename": file.originalname,
                "contentType": file.mimetype
            }
        }
    };
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';

    // Pass group_id as query param to Flask
    msg.url = "http://localhost:5000/detect?group_id=" + group_id;
} else {
    msg.payload = {};
}

return [msg, null]; // Send to first output (success)

msg.payload = { error: msg.error ? msg.error.message : 'Unknown error' };
msg.statusCode = 500;
return msg;
